        return -1;
    }

    bytes_read = fread(buffer, 1, sizeof(buffer), fptr_in); // Read from the file into buffer
    if(bytes_read == 0) {
        printf("The input file is empty.\n");
        fclose(fptr_in);
        return -1;
    }

    for(size_t i = 0; i < bytes_read; ++i) // Calculate the checksum
        checksum += (unsigned char)buffer[i];

    if(checksum == 0) {
        printf("The buffer is empty.\n");
        fclose(fptr_in);
        return -1;
    }

    fptr_out = fopen("output.txt", "wb"); // Open output file in binary write mode
    if(fptr_out == NULL) {
        printf("Could not open the output file\n");
        fclose(fptr_in);
        return -1;
    }

    fprintf(fptr_out, "Bytes read: %zu\nChecksum: %zu", bytes_read, checksum); // Write to the file

    fclose(fptr_in); // Close both files
    fclose(fptr_out);

    return 0;
}
