```c
#include <stdio.h>

int scan(char *buffer) {
    int count = 0;
    char c;

    // Loop until newline character is found or 1023 characters are read
    while (count < 1023 && ((c = getchar()) != '\n')) {
        buffer[count] = c;
        ++count;
    }

    return count;
}

int main() {
