['Here's how you can implement this task in C:

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

void trim_trailing(char *str) {
    int index = strlen(str) - 1;
    while (index >= 0 && isspace((unsigned char)str[index])) {
        str[index--] = '\0';
    }
}

int main(int argc, char **argv) {

    // Check that exactly one argument is provided and it's a string.
    if (argc != 2) {
        printf("Usage: %s [string]\n", argv[0]);
        return 1;
    }

    char *input = argv[1];

    // Trim trailing whitespace from input string
    trim_trailing(input);

    int i, j;
    for (i = 0; input[i] != '\0'; ++i) {
        if (isspace((unsigned char)input[i]) && (i == 0 || isspace((unsigned char)input[i - 1]))) {
            for (j = i + 1; input[j] != '\0'; ++j) {
                input[j-1] = input[j];
            }
            input[--j] = '\0';
        }
    }

    // Null terminate the string.
    input[i] = '\0';

    printf("Trimmed: %s\n", input);
    return 0;
}
```
Please note that this code will trim any trailing whitespace (spaces, tabs, newlines) from the provided command-line argument. It doesn't specifically check for newlines and will remove all consecutive occurrences of them as well. Also, it assumes that the input string is properly null terminated.
