#include "onion/types.h"
#include "onion/onion.h"
#include "onion/request.h"
#include "onion/response.h"

void http_hello_page(OnionResponse *res, OnionRequest *req) {
    char *username = onion_request_get_post_arg_multi(req, "username");

    if (username == NULL) {
        onion_response_printf(res, "Error: username not provided.");
        return;
    }

    const char *outputbuf = malloc(sizeof(char)*(strlen("<html><body>Hello ") + strlen(username) + strlen("</body></html>") + 1));
    sprintf((char*) outputbuf, "<html><body>Hello %s</body></html>", username);

    onion_response_write0(res, (void *)outputbuf, O_WRITE); // write the response body to the response stream
    free(username);
}
```
